{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "The closest analogue, an m-chlorophenyl urea benzothiazole, was detected in brain after oral dosing in vivo, demonstrating that the shared m-chlorophenyl urea motif can confer meaningful BBB access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "The urea-linked N-methyl cyclic amidinone L-365,260 showed very low BBB permeability and brain uptake <0.8% dose/g in mice, indicating that this general urea/cyclic-amide class can be subject to poor CNS exposure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "A urea-containing chlorophenyl compound reached brain concentrations about 15-fold higher than plasma in mice, supporting CNS access for small urea-based molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Bupropion, a small neutral chlorophenyl-containing drug with modest logP, achieved a Kp,uu of 1.9 in rat brain microdialysis, showing that similar physicochemical features do not preclude high unbound brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "The structurally related CCK antagonist YF476, which combines an aryl urea with an N-methyl cyclic amidinone, showed low brain radioactivity after IV injection in rats, suggesting possible efflux liability for this scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogue (m-chlorophenyl urea benzothiazole) crosses the BBB, and multiple small chlorophenyl/urea-containing molecules show high brain exposure; the query's low molecular weight, neutral charge, and moderate passive properties support meaningful CNS access. The contradictory benzodiazepine urea data come from much larger, more lipophilic scaffolds and are less transferable.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or Kp,uu measurement exists for the query molecule.",
    "All available analogues have low-to-moderate Morgan similarity to the query.",
    "The efflux-transporter status of the query is unknown.",
    "No human or non-human primate CNS exposure data are available for this exact chemotype."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

